const { MessageEmbed } = require('discord.js');
const { msg } = cache;

// Pobieramy zmienne
let clever = tempVars("ai");
const fi = tempVars("memava");
const ft = tempVars("memname");

// --- FIX: Zabezpieczenie przed błędem EMBED_DESCRIPTION ---
// Jeśli clever jest puste, dajemy tekst zastępczy zamiast wywalać błąd
if (!clever || String(clever).trim() === "undefined" || String(clever).trim() === "") {
    clever = "Zaraza... Vesemir nie odpowiedział. Sprawdź czy API działa lub czy nie użyłeś dziwnych znaków.";
} else {
    clever = String(clever); // Upewniamy się, że to na pewno String
}

const embed = new MessageEmbed()
.setColor('#2f3136')
    .setDescription(clever)
    .setFooter({ 
        text: ft ? String(ft) : "Wiedźmin", 
        iconURL: fi ? String(fi) : null 
    });

// Wysyłamy odpowiedź
msg.reply({ embeds: [embed], allowedMentions: { repliedUser: false } })
    .then(() => this.callNextAction(cache))
    .catch(err => console.error("Błąd wysyłania: " + err));
